package com.secretshield.service;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import com.secretshield.dto.*;import com.secretshield.entity.*;import com.secretshield.exception.*;import com.secretshield.repository.*;import tools.jackson.databind.json.JsonMapper;
@Service public class CiIngestionService {
 private final ScanRepository scans;private final ProjectRepositoryRepository repositories;private final List<FindingResultSink> sinks;private final JsonMapper json;
 public CiIngestionService(ScanRepository s,ProjectRepositoryRepository r,List<FindingResultSink> f,JsonMapper j){scans=s;repositories=r;sinks=f;json=j;}
 public record Result(ScanDto scan,boolean created){}
 @Transactional public Result ingest(long repoId,CiScanResultRequest in){var repo=repositories.findLockedById(repoId).orElseThrow(()->new ResourceNotFoundException("Repository not found"));if(!repo.isActive())throw new ConflictException("Repository is inactive");Validated v=validate(in);String digest=digest(v);
  var existing=scans.findByRepositoryIdAndRunIdAndRunAttemptAndCommitSha(repoId,v.runId,v.attempt,v.sha);if(existing.isPresent()){if(!digest.equals(existing.get().getPayloadDigest()))throw new ConflictException("Conflicting result replay");return new Result(ScanDto.from(existing.get()),false);}
  var now=LocalDateTime.now(ZoneOffset.UTC);var scan=scans.saveAndFlush(Scan.builder().repository(repo).runId(v.runId).runAttempt(v.attempt).commitSha(v.sha).branch(v.branch).trigger(v.trigger).scannerVersion(v.version).status(v.status).failureCode(v.failure).payloadDigest(digest).startedAt(now).completedAt(now).build());for(var sink:sinks)sink.persist(scan,v.findings);return new Result(ScanDto.from(scan),true);}
 private Validated validate(CiScanResultRequest x){ScanTrigger trigger;ScanStatus status;try{trigger=ScanTrigger.valueOf(x.trigger());status=ScanStatus.valueOf(x.status());}catch(Exception e){throw invalid();}if(trigger==ScanTrigger.MANUAL||!(status==ScanStatus.CLEAN||status==ScanStatus.FINDINGS_DETECTED||status==ScanStatus.FAILED))throw invalid();String run=x.runId()==null?null:x.runId().strip();if(run==null||!run.matches("[A-Za-z0-9._:-]{1,200}")||x.runAttempt()==null||x.runAttempt()<1)throw invalid();String version=x.scannerVersion()==null?null:x.scannerVersion().strip();if(version==null||!version.matches("[A-Za-z0-9._+/-]{1,100}"))throw invalid();List<SanitizedFindingInput> findings=x.findings();String failure=x.failureCode();if(status==ScanStatus.CLEAN&&(!findings.isEmpty()||failure!=null)||status==ScanStatus.FINDINGS_DETECTED&&(findings.isEmpty()||failure!=null)||status==ScanStatus.FAILED&&(!findings.isEmpty()||failure==null))throw invalid();if(failure!=null)failure=ScanService.failure(failure);for(var f:findings){if(f.filePath().startsWith("/")||f.filePath().startsWith("\\")||f.filePath().contains("\\")||Arrays.asList(f.filePath().split("/")).contains(".."))throw invalid();}return new Validated(run,x.runAttempt(),ScanService.sha(x.commitSha()),ScanService.strictBranch(x.branch()),trigger,version,status,failure,List.copyOf(findings));}
 private String digest(Validated v){try{byte[] data=json.writeValueAsBytes(v);return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));}catch(Exception e){throw new IllegalStateException("Unable to digest result");}}
 private record Validated(String runId,Integer attempt,String sha,String branch,ScanTrigger trigger,String version,ScanStatus status,String failure,List<SanitizedFindingInput> findings){}
 private static jakarta.validation.ConstraintViolationException invalid(){return new jakarta.validation.ConstraintViolationException("Invalid CI result",Set.of());}
}
